    "source": "surface-height-map/v0.2.0/src/main.js",
    "fn": "openGotoXYDialog",
    "requires": "state.positionMode, state.workPosition, state.machinePosition, readTravelLimits(), readCoordinateOffsets()",
    "code": "async function openGotoXYDialog() {\n    if (state.busy || !state.controllerHomed || !Number.isFinite(state.homeMachineZ)) return;\n    const position = state.positionMode === 'wpos' ? state.workPosition : state.machinePosition;\n    if (!position || !position.slice(0, 2).every(Number.isFinite)) {\n        setNotice(`Cannot open GOTO XY: the ${state.positionMode.toUpperCase()} position is not available yet.`, 'error');\n        return;\n    }\n    $('gotoXYMode').textContent = state.positionMode === 'wpos'\n        ? 'Enter coordinates in the active work coordinate system (WPOS).'\n        : 'Enter machine coordinates (MPOS).';\n    $('gotoX').value = position[0].toFixed(3);\n    $('gotoY').value = position[1].toFixed(3);\n    state.gotoXYContext = null;\n    $('gotoX').disabled = true;\n    $('gotoY').disabled = true;\n    $('confirmGotoXY').disabled = true;\n    $('gotoXYError').className = 'goto-xy-error';\n    $('gotoXYError').textContent = 'Reading controller travel limits and coordinate offsets…';\n    $('gotoXYError').hidden = false;\n    $('gotoXYDialog').showModal();\n    $('gotoX').focus();\n    const mode = state.positionMode;\n    try {\n        const limits = await readTravelLimits();\n        const activeWcs = await readActiveWcs();\n        const offsets = await readCoordinateOffsets(activeWcs);\n        const offsetX = mode === 'wpos' ? offsets[activeWcs][0] + offsets.G92[0] : 0;\n        const offsetY = mode === 'wpos' ? offsets[activeWcs][1] + offsets.G92[1] : 0;\n        const fullRetractWpos = n('fullRetract');\n        const machineRetractZ = fullRetractWpos + offsets[activeWcs][2] + offsets.G92[2];\n        if (!Number.isFinite(fullRetractWpos) || !Number.isFinite(machineRetractZ)\n            || machineRetractZ < limits.minZ || machineRetractZ > limits.maxZPosition) {\n            throw new Error(`Full Retract Height WPOS Z${fullRetractWpos} maps to machine Z${machineRetractZ.toFixed(3)}, outside allowed Z travel ${limits.minZ} to ${limits.maxZPosition} mm.`);\n        }\n        const machineMinX = limits.minX;\n        const machineMaxX = limits.maxXPosition ?? limits.maxX;\n        const machineMinY = limits.minY;\n        const machineMaxY = limits.maxYPosition ?? limits.maxY;\n        state.gotoXYContext = {\n            mode, limits, offsetX, offsetY, fullRetractWpos, machineRetractZ,\n            minX: machineMinX - offsetX, maxX: machineMaxX - offsetX,\n            minY: machineMinY - offsetY, maxY: machineMaxY - offsetY,\n        };\n        for (const [axis, min, max] of [\n            ['X', state.gotoXYContext.minX, state.gotoXYContext.maxX],\n            ['Y', state.gotoXYContext.minY, state.gotoXYContext.maxY],\n        ]) {\n            const input = $(`goto${axis}`);\n            input.min = min.toFixed(3);\n            input.max = max.toFixed(3);\n            input.disabled = false;\n        }\n        const limitFlags = [\n            limits.softLimitsEnabled ? '$20 soft limits on' : '$20 soft limits off',\n            limits.hardLimitsEnabled ? '$21 hard limits on' : '$21 hard limits off',\n        ].join('; ');\n        $('gotoXYError').textContent = `Allowed ${mode.toUpperCase()} range: X ${state.gotoXYContext.minX.toFixed(3)} to ${state.gotoXYContext.maxX.toFixed(3)} mm; Y ${state.gotoXYContext.minY.toFixed(3)} to ${state.gotoXYContext.maxY.toFixed(3)} mm. Full retract maps to machine Z${machineRetractZ.toFixed(3)} mm (${limitFlags}).`;\n        updateGotoXYValidation();\n    } catch (error) {\n        state.gotoXYContext = null;\n        $('gotoXYError').className = 'goto-xy-error';\n        $('gotoXYError').textContent = `Cannot check this move against controller limits: ${error.message}. Move is disabled.`;\n        $('gotoXYError').hidden = false;\n        await logCalibration(`GOTO XY limit check failed: ${error.message}`);\n    }\n}",
