    "code": "function updateGotoXYValidation() {\n    const context = state.gotoXYContext;\n    const error = $('gotoXYError');\n    const move = $('confirmGotoXY');\n    if (!context) { move.disabled = true; return; }\n    const xText = $('gotoX').value.trim(), yText = $('gotoY').value.trim();\n    const x = Number(xText), y = Number(yText);\n    if (!xText || !yText || ![x, y].every(Number.isFinite)) {\n        move.disabled = true;\n        error.className = 'goto-xy-error';\n        error.textContent = 'Enter valid X and Y coordinates to check the target.';\n        error.hidden = false;\n        return;\n    }\n    const machineTarget = { x: x + context.offsetX, y: y + context.offsetY };\n    try {\n        validateMachineTarget(machineTarget, context.limits);\n        move.disabled = false;\n        error.className = 'goto-xy-error success';\n        error.textContent = `Target is within machine travel (MPOS X${machineTarget.x.toFixed(3)} Y${machineTarget.y.toFixed(3)}).`;\n    } catch {\n        move.disabled = true;\n        error.className = 'goto-xy-error';\n        error.textContent = `Warning: this target is outside machine XY travel and may trigger a soft or hard limit. Allowed ${context.mode.toUpperCase()} range: X ${context.minX.toFixed(3)} to ${context.maxX.toFixed(3)} mm; Y ${context.minY.toFixed(3)} to ${context.maxY.toFixed(3)} mm.`;\n    }\n    error.hidden = false;\n}",
