    "fn": "goToXYFromDialog",
    "requires": "statusSnapshot(), readTravelLimits(), readFreshMachinePosition(), readCoordinateOffsets(), confirmed probe parser contract, moveXYWithProbeGuard(), waitForMachinePosition()",
    "code": "async function goToXYFromDialog() {\n    const xText = $('gotoX').value.trim();\n    const yText = $('gotoY').value.trim();\n    const x = Number(xText), y = Number(yText);\n    const validationError = $('gotoXYError');\n    if (!state.gotoXYContext || $('confirmGotoXY').disabled) return;\n    if (!xText || !yText || ![x, y].every(Number.isFinite)) {\n        validationError.textContent = 'Enter valid X and Y coordinates in millimetres.';\n        validationError.hidden = false;\n        return;\n    }\n    if (state.busy || !state.controllerHomed) return;\n    const mode = state.positionMode;\n    const target = { x: Number(x.toFixed(3)), y: Number(y.toFixed(3)) };\n    $('gotoXYDialog').close();\n    state.busy = true;\n    await refreshUi();\n    setNotice(`Moving to ${mode.toUpperCase()} X${target.x.toFixed(3)} Y${target.y.toFixed(3)} while preserving Z…`);\n    try {\n        const initial = await statusSnapshot();\n        if (initial.state !== 'Idle') throw new Error(`GOTO XY requires an idle machine (current state: ${initial.state}).`);\n        const limits = await readTravelLimits();\n        let machineTarget;\n        let command;\n        const activeWcs = await readActiveWcs();\n        const offsets = await readCoordinateOffsets(activeWcs);\n        const fullRetractWpos = n('fullRetract');\n        const machineRetractZ = fullRetractWpos + offsets[activeWcs][2] + offsets.G92[2];\n        if (!Number.isFinite(machineRetractZ) || machineRetractZ < limits.minZ || machineRetractZ > limits.maxZPosition) {\n            throw new Error(`Full Retract Height maps to machine Z${machineRetractZ.toFixed(3)} mm, outside allowed Z travel ${limits.minZ} to ${limits.maxZPosition} mm.`);\n        }\n        const currentMpos = await readFreshMachinePosition();\n        if (mode === 'mpos') {\n            machineTarget = validateMachineTarget(target, limits);\n            command = `G21 G90 G53 G0 X${target.x.toFixed(3)} Y${target.y.toFixed(3)}`;\n        } else {\n            const wcsOffset = offsets[activeWcs], g92Offset = offsets.G92;\n            machineTarget = validateMachineTarget({\n                x: target.x + wcsOffset[0] + g92Offset[0],\n                y: target.y + wcsOffset[1] + g92Offset[1],\n            }, limits);\n            command = `G21 G90 G53 G0 X${machineTarget.x.toFixed(3)} Y${machineTarget.y.toFixed(3)}`;\n        }\n        await machine.setBusy(true, `GOTO ${mode.toUpperCase()} X${target.x.toFixed(3)} Y${target.y.toFixed(3)}`);\n        invalidateWposOrigin('Machine moved to a new XY position. Probe the selected WPOS origin again before calibration.');\n        const raisingZ = currentMpos[2] < machineRetractZ - 0.001;\n        await logCalibration(`GOTO XY requested: mode=${mode.toUpperCase()} target X${target.x.toFixed(3)} Y${target.y.toFixed(3)}; current machine Z${currentMpos[2].toFixed(3)}, full retract target machine Z${machineRetractZ.toFixed(3)}; ${raisingZ ? 'raising Z before XY' : 'keeping Z at its current height'}; machine command=${command}.`);\n        if (raisingZ) {\n            await sendAndWait(`G21 G90 G53 G0 Z${machineRetractZ.toFixed(3)}`, 30000);\n            await waitForMachinePosition({ Z: machineRetractZ }, ['Z'], 30000);\n        }\n        await moveXYWithProbeGuard(command, `to ${mode.toUpperCase()} X${target.x.toFixed(3)} Y${target.y.toFixed(3)}`);\n        const actualMpos = await waitForMachinePosition({ X: machineTarget.x, Y: machineTarget.y }, ['X', 'Y'], 30000);\n        const actualWpos = [actualMpos[0] - offsets[activeWcs][0] - offsets.G92[0], actualMpos[1] - offsets[activeWcs][1] - offsets.G92[1]];\n        state.machinePosition = actualMpos;\n        state.workPosition = [...actualWpos, state.workPosition?.[2] ?? 0];\n        renderMachineDro();\n        const confirmed = Math.abs(actualMpos[0] - machineTarget.x) <= 0.1 && Math.abs(actualMpos[1] - machineTarget.y) <= 0.1\n            && Math.abs(actualWpos[0] - target.x) <= 0.1 && Math.abs(actualWpos[1] - target.y) <= 0.1;\n        await logCalibration(`GOTO XY verification from fresh GRBL status: mode=${mode.toUpperCase()} requested X${target.x.toFixed(3)} Y${target.y.toFixed(3)}; expected MPos X${machineTarget.x.toFixed(3)} Y${machineTarget.y.toFixed(3)}; reported MPos X${actualMpos[0].toFixed(3)} Y${actualMpos[1].toFixed(3)}; calculated WPos X${actualWpos[0].toFixed(3)} Y${actualWpos[1].toFixed(3)}.`);\n        if (!confirmed) {\n            throw new Error(`Controller position does not match the requested ${mode.toUpperCase()} XY. Fresh status reports MPos X${actualMpos[0].toFixed(3)} Y${actualMpos[1].toFixed(3)} and calculated WPos X${actualWpos[0].toFixed(3)} Y${actualWpos[1].toFixed(3)}.`);\n        }\n        setNotice(`Arrived at ${mode.toUpperCase()} X${target.x.toFixed(3)} Y${target.y.toFixed(3)}; Z is at or above Full Retract Height.`, 'success');\n    } catch (error) {\n        await logCalibration(`GOTO XY ERROR: ${error.message}`);\n        setNotice(error.message, 'error');\n    } finally {\n        state.busy = false;\n        try { await machine.setBusy(false); } catch { /* connection may have closed */ }\n        await refreshUi();\n    }\n}",
