    "requires": "limits.minX/maxX/minY/maxY; limits.minZ/maxZPosition for Z where applicable",
    "code": "export function validateMachineTarget({ x, y }, limits) {\n    if (![limits.maxX, limits.maxY].every((limit) => Number.isFinite(limit) && limit > 0)) {\n        throw new Error('Could not read valid machine XY travel limits from $130/$131.');\n    }\n    if (![x, y].every(Number.isFinite)) throw new Error('Enter valid machine-coordinate X and Y positions.');\n    const maxX = limits.maxXPosition ?? limits.maxX;\n    const maxY = limits.maxYPosition ?? limits.maxY;\n    if (x < limits.minX || x > maxX || y < limits.minY || y > maxY) {\n        throw new Error(`Position must be within machine travel: X ${limits.minX}–${maxX} mm, Y ${limits.minY}–${maxY} mm.`);\n    }\n    return { x: Number(x.toFixed(4)), y: Number(y.toFixed(4)) };\n}",
